#!/usr/bin/env python3
"""Reviewed one-attempt compiler launcher. Preparation only until final pin is installed."""
import hashlib
import json
import os
from pathlib import Path
import subprocess
import threading
from datetime import datetime, timezone

EVIDENCE = Path('/tmp/puni-coupled-compiler-attempt-20261107')
EXPECTED_SHA256 = '5a68d5d06d102865d80323a882070ad065254eff0d0948acba43a8539cba5c73'
OPERATIONS = []
LOCK = threading.Lock()
CHILDREN = []
READERS = []
os.umask(0o077)


def observe(key, action):
    with LOCK:
        if any(record['key'] == key for record in OPERATIONS):
            raise RuntimeError('duplicate launcher operation: ' + key)
        record = {'key': key, 'state': 'entered', 'joined': False}
        OPERATIONS.append(record)
    try:
        value = action()
    except BaseException as cause:
        record.update(state='rejected', joined=True, cause=repr(cause))
        raise
    record.update(state='fulfilled', joined=True)
    return value


def read_bytes(key, path):
    return observe(key, lambda: path.read_bytes())


def digest_bytes(contents):
    return hashlib.sha256(contents).hexdigest()


def write_once(key, name, value):
    def write():
        with (EVIDENCE / name).open('x', encoding='utf-8') as output:
            json.dump(value, output, indent=2)
            output.write('\n')
    observe(key, write)


def snapshot(expected, phase):
    root = Path(expected['sourceRoot'])
    head = observe(phase + ':git.head', lambda: subprocess.check_output(
        ['git', 'rev-parse', 'HEAD'], cwd=root, text=True)).strip()
    dirty = observe(phase + ':git.status', lambda: subprocess.check_output(
        ['git', 'status', '--porcelain=v1', '--untracked-files=all'], cwd=root, text=True))
    pins = {}
    for pin in expected['externalPins']:
        path = Path(pin['path'])
        canonical = observe(phase + ':realpath:' + str(path), lambda: str(path.resolve(strict=True)))
        status = observe(phase + ':lstat:' + str(path), path.lstat)
        contents = read_bytes(phase + ':read:' + str(path), path)
        pins[str(path)] = {'canonical': canonical, 'bytes': len(contents),
                           'statBytes': status.st_size, 'mode': status.st_mode & 0o7777,
                           'sha256': digest_bytes(contents), 'isRegular': __import__('stat').S_ISREG(status.st_mode)}
    return {'head': head, 'dirty': dirty, 'pins': pins}


def check_snapshot(captured, expected):
    if captured['head'] != expected['head'] or captured['dirty'] != '':
        raise RuntimeError('source HEAD or clean publication differs')
    if captured['pins'] != {pin['path']: {key: pin[key] for key in (
            'canonical', 'bytes', 'statBytes', 'mode', 'sha256', 'isRegular')}
            for pin in expected['externalPins']}:
        raise RuntimeError('external issuer/config/compiler/parser/authority pins differ')


def drain(pipe, name, state):
    def copy():
        with (EVIDENCE / (name + '.raw')).open('xb') as output:
            while True:
                chunk = pipe.read(65536)
                if chunk == b'':
                    state[name + 'EOF'] = True
                    break
                output.write(chunk)
    try:
        observe('stream:' + name + ':drain', copy)
    except BaseException as cause:
        state[name + 'Failure'] = repr(cause)
    finally:
        observe('stream:' + name + ':close', pipe.close)


def success_keys(expected):
    keys = ['expected.read', 'runtime.list', 'attempt.claim']
    for phase in ('before', 'after'):
        if phase == 'after':
            keys += ['preflight.write', 'child.spawn', 'child.pgid', 'started.write',
                     'stream:stdout:start', 'stream:stderr:start',
                     'stream:stdout:drain', 'stream:stdout:close',
                     'stream:stderr:drain', 'stream:stderr:close',
                     'child.wait', 'stream:stdout:join', 'stream:stderr:join']
        keys += [phase + ':git.head', phase + ':git.status']
        for pin in expected['externalPins']:
            keys += [phase + ':' + operation + ':' + pin['path']
                     for operation in ('realpath', 'lstat', 'read')]
    keys += ['stream:stdout:readback', 'stream:stderr:readback', 'receipt.write']
    return keys


def main():
    expected_raw = read_bytes('expected.read', EVIDENCE / 'expected.json')
    if digest_bytes(expected_raw) != EXPECTED_SHA256:
        raise RuntimeError('final externally reviewed expected manifest not pinned')
    expected = json.loads(expected_raw)
    if expected['status'] != 'FROZEN-REVIEWED' or len(expected['head']) != 40:
        raise RuntimeError('publication freeze incomplete')
    if not expected['lease']['active'] or not expected['lease']['scope']:
        raise RuntimeError('Root isolated source/install/config/layout no-writer lease absent')
    if len(success_keys(expected)) != len(set(success_keys(expected))):
        raise RuntimeError('launcher expected operation keys repeat')
    if observe('runtime.list', lambda: list((EVIDENCE / 'runtime').iterdir())):
        raise RuntimeError('runtime directory is not fresh')
    write_once('attempt.claim', 'attempt.claim.json', {'startedUTC': datetime.now(timezone.utc).isoformat(),
               'expectedSha256': EXPECTED_SHA256, 'oneAttempt': True})
    before = snapshot(expected, 'before')
    check_snapshot(before, expected)
    environment = dict(expected['env'])
    environment['KCT5_EXPECTED_SHA256'] = EXPECTED_SHA256
    write_once('preflight.write', 'preflight.json', {'argv': expected['argv'], 'env': environment,
               'sourceBefore': before, 'lease': expected['lease'],
               'successOperationKeys': success_keys(expected), 'limits': expected['limits']})
    child = observe('child.spawn', lambda: subprocess.Popen(expected['argv'], cwd=expected['sourceRoot'],
            env=environment, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            start_new_session=True, umask=0o022, close_fds=True))
    CHILDREN.append(child)
    if child.stdout is None or child.stderr is None:
        raise RuntimeError('actual child streams absent; retained child must still be joined')
    def pgid():
        try:
            return {'observed': os.getpgid(child.pid)}
        except ProcessLookupError:
            return {'alreadyExitedBeforeObservation': True}
    state = {}
    # Start both drains before writing started evidence: an evidence error cannot strand a full pipe.
    for name, pipe in [('stdout', child.stdout), ('stderr', child.stderr)]:
        reader = threading.Thread(target=drain, args=(pipe, name, state), daemon=False)
        READERS.append((name, reader))
        observe('stream:' + name + ':start', reader.start)
    group = observe('child.pgid', pgid)
    started_error = None
    try:
        write_once('started.write', 'started.json', {'pid': child.pid, 'pgid': group,
                   'sessionLeaderPid': child.pid, 'startedUTC': datetime.now(timezone.utc).isoformat()})
    except BaseException as cause:
        started_error = repr(cause)
    returncode = observe('child.wait', child.wait)
    for name, reader in READERS:
        observe('stream:' + name + ':join', reader.join)
    after = None
    postflight_error = None
    try:
        after = snapshot(expected, 'after')
        check_snapshot(after, expected)
    except BaseException as cause:
        postflight_error = repr(cause)
    streams = {}
    for name in ('stdout', 'stderr'):
        contents = read_bytes('stream:' + name + ':readback', EVIDENCE / (name + '.raw'))
        streams[name] = {'bytes': len(contents), 'sha256': digest_bytes(contents)}
    observed_keys = [record['key'] for record in OPERATIONS] + ['receipt.write']
    roster_matches = len(observed_keys) == len(success_keys(expected)) and set(observed_keys) == set(success_keys(expected))
    receipt = {'completedUTC': datetime.now(timezone.utc).isoformat(), 'pid': child.pid, 'pgid': group,
               'exitCode': returncode if returncode >= 0 else None, 'signal': -returncode if returncode < 0 else None,
               'streams': streams, 'readers': state, 'sourceAfter': after,
               'sourceUnchanged': after == before, 'postflightError': postflight_error,
               'startedEvidenceError': started_error, 'operations': OPERATIONS.copy(),
               'operationRosterMatches': roster_matches, 'receiptWrite': 'record checked after actual write',
               'outputImported': False, 'scannerBridge': 'UNQUALIFIED'}
    write_once('receipt.write', 'receipt.json', receipt)
    print(json.dumps({'launcherOperations': OPERATIONS, 'receiptJoined': True}), flush=True)
    if (not roster_matches or any(record['state'] != 'fulfilled' or not record['joined'] for record in OPERATIONS)
            or state.get('stdoutEOF') is not True or state.get('stderrEOF') is not True
            or postflight_error is not None or started_error is not None or after != before):
        return 1
    return returncode if returncode >= 0 else 128 - returncode


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as cause:
        # No signal, kill, retry or timeout. Real children/readers remain retained and joined.
        for child in CHILDREN:
            observe('failure:child.wait:' + str(child.pid), child.wait)
        for name, reader in READERS:
            observe('failure:stream.join:' + name, reader.join)
        write_once('launcher.failure.write', 'launcher-failure.json', {
            'outcome': 'failed-unqualified', 'cause': repr(cause), 'operations': OPERATIONS.copy(),
            'children': [{'pid': child.pid, 'actualReturncode': child.returncode} for child in CHILDREN],
            'outputImported': False})
        raise

